_label":"2031-09"}]}$payload$::jsonb;
 v_owner uuid;v_case uuid;
begin
 select owner_user_id into v_owner from public.workspaces where id='d621017c-e9bd-4334-a07f-5e7b6d31ef6e';
 if v_owner is null then select user_id into v_owner from public.workspace_members where workspace_id='d621017c-e9bd-4334-a07f-5e7b6d31ef6e'order by case when role='owner'then 0 else 1 end limit 1;end if;
 if v_owner is null then raise exception'Could not resolve Nikolaus Skene owner user';end if;
 select id into v_case from public.private_insolvency_cases where owner_user_id=v_owner and name='Private Insolvency';
 if v_case is null then insert into public.private_insolvency_cases(owner_user_id,name,currency,notes)values(v_owner,'Private Insolvency','EUR','Migrated from legacy payment tracker qednxzolyqzthukqzooh on 2026-08-14')returning id into v_case;end if;
 if exists(select 1 from public.private_insolvency_creditors where case_id=v_case)or exists(select 1 from public.private_insolvency_plans where case_id=v_case)or exists(select 1 from public.private_insolvency_schedule where case_id=v_case)or exists(select 1 from public.private_insolvency_payments where case_id=v_case)then raise exception'Private insolvency case already contains migrated data; import stopped';end if;

 insert into public.private_insolvency_creditors(id,case_id,legacy_id,name,contact_email,notes,created_at)
 select x.id,v_case,x.id,x.name,x.contact_email,x.notes,x.created_at from jsonb_to_recordset(v_export->'organizations')as x(id uuid,name text,contact_email text,notes text,created_at timestamptz);
 insert into public.private_insolvency_plans(id,case_id,creditor_id,legacy_id,monthly_amount,start_date,months,due_day,disputed_amount,repay_percent,repay_total,active,notes,created_at)
 select x.id,v_case,x.org_id,x.id,x.monthly_amount,x.start_date,x.months,x.due_day,x.disputed_amount,x.repay_percent,x.repay_total,x.active,x.notes,x.created_at
 from jsonb_to_recordset(v_export->'payment_plans')as x(id uuid,org_id uuid,monthly_amount numeric,start_date date,months integer,due_day integer,disputed_amount numeric,repay_percent numeric,repay_total numeric,active boolean,notes text,created_at timestamptz);
 insert into public.private_insolvency_schedule(id,case_id,plan_id,creditor_id,legacy_id,due_date,amount_due,period_label,created_at)
 select x.id,v_case,x.plan_id,x.org_id,x.id,x.due_date,x.amount_due,x.period_label,x.created_at
 from jsonb_to_recordset(v_export->'scheduled_payments')as x(id uuid,plan_id uuid,org_id uuid,due_date date,amount_due numeric,period_label text,created_at timestamptz);
 insert into public.private_insolvency_payments(id,case_id,schedule_id,creditor_id,legacy_id,paid_date,amount_paid,reference,method,note,source,is_voided,voided_at,voided_by,void_reason,created_at)
 select x.id,v_case,x.scheduled_id,x.org_id,x.id,x.paid_date,x.amount_paid,x.reference,x.method,x.note,coalesce(x.source,'legacy'),coalesce(x.is_voided,false),x.voided_at,
  case when x.voided_by is not null and exists(select 1 from auth.users u where u.id=x.voided_by)then x.voided_by else null end,x.void_reason,x.created_at
 from jsonb_to_recordset(v_export->'payments')as x(id uuid,scheduled_id uuid,org_id uuid,paid_date date,amount_paid numeric,reference text,method text,note text,source text,is_voided boolean,voided_at timestamptz,voided_by uuid,void_reason text,created_at timestamptz);
 if(select count(*)from public.private_insolvency_creditors where case_id=v_case)<>(v_export#>>'{control_totals,organizations}')::integer then raise exception'Creditor count mismatch';end if;
 if(select count(*)from public.private_insolvency_plans where case_id=v_case)<>(v_export#>>'{control_totals,plans}')::integer then raise exception'Plan count mismatch';end if;
 if(select count(*)from public.private_insolvency_schedule where case_id=v_case)<>(v_export#>>'{control_totals,scheduled}')::integer then raise exception'Schedule count mismatch';end if;
 if(select count(*)from public.private_insolvency_payments where case_id=v_case)<>(v_export#>>'{control_totals,payments}')::integer then raise exception'Payment count mismatch';end if;
 if abs((select sum(amount_due)from public.private_insolvency_schedule where case_id=v_case)-(v_export#>>'{control_totals,scheduled_total}')::numeric)>.01 then raise exception'Schedule total mismatch';end if;
 if abs((select sum(amount_paid)filter(where not is_voided)from public.private_insolvency_payments where case_id=v_case)-(v_export#>>'{control_totals,payments_total}')::numeric)>.01 then raise exception'Payment total mismatch';end if;
 insert into public.private_insolvency_audit(case_id,entity_type,entity_id,action,details,created_by)values(v_case,'case',v_case,'legacy_import',v_export->'control_totals',v_owner);
end $$;
commit;
select jsonb_build_object(
 'creditors',(select count(*)from public.private_insolvency_creditors),'plans',(select count(*)from public.private_insolvency_plans),
 'scheduled',(select count(*)from public.private_insolvency_schedule),'scheduled_total',(select sum(amount_due)from public.private_insolvency_schedule),
 'payments',(select count(*)from public.private_insolvency_payments),'payments_total',(select sum(amount_paid)filter(where not is_voided)from public.private_insolvency_payments),
 'open_balance',(select sum(greatest(balance,0))from public.v_private_insolvency_schedule),
 'isolated_from_company_ledgers',true
+)as import_verification;

